//! "Is there a new version?" — once a day, if the user allows it. Nothing is
//! downloaded or installed: the app shows a notification whose button opens the
//! release page on our website. The request carries only the app's version
//! (in the User-Agent); no identifier, no file names, nothing about the PC.

use serde_json::{json, Value};

/// The release feed, generated by the website (repositories/website, /latest.json).
/// Change it together with SITE in the website when the domain is final.
pub const FEED_URL: &str = "https://mqkit.com/latest.json";
/// Links opened from the notification must stay on this site.
pub const SITE_PREFIX: &str = "https://mqkit.com/";

fn parse_version(v: &str) -> Vec<u64> {
    v.trim_start_matches('v').split(['.', '-', '+']).take(3).map(|p| p.parse().unwrap_or(0)).collect()
}

fn newer(remote: &str, local: &str) -> bool {
    let (r, l) = (parse_version(remote), parse_version(local));
    for i in 0..3 {
        let (a, b) = (r.get(i).copied().unwrap_or(0), l.get(i).copied().unwrap_or(0));
        if a != b {
            return a > b;
        }
    }
    false
}

/// `{ available, version, url, notes }`. The feed:
/// `{ "version": "1.1.0", "url": "https://mqkit.com/changelog/#v1-1-0", "notes": { "ro": "…", "en": "…" } }`
pub fn check() -> Result<Value, String> {
    let local = env!("CARGO_PKG_VERSION");
    let agent: ureq::Agent = ureq::Agent::config_builder()
        .timeout_global(Some(std::time::Duration::from_secs(10)))
        .user_agent(format!("MQKit/{local}"))
        .build()
        .into();
    let mut resp = agent.get(FEED_URL).call().map_err(|e| e.to_string())?;
    let text = resp.body_mut().with_config().limit(64 * 1024).read_to_string().map_err(|e| e.to_string())?;
    let feed: Value = serde_json::from_str(&text).map_err(|e| e.to_string())?;
    let version = feed["version"].as_str().unwrap_or("");
    let url = feed["url"].as_str().filter(|u| u.starts_with(SITE_PREFIX)).unwrap_or(SITE_PREFIX);
    Ok(json!({
        "available": !version.is_empty() && newer(version, local),
        "version": version,
        "current": local,
        "url": url,
        "notes": feed.get("notes").cloned().unwrap_or(Value::Null),
    }))
}

#[cfg(test)]
mod tests {
    #[test]
    fn versions() {
        assert!(super::newer("1.1.0", "1.0.9"));
        assert!(super::newer("v0.2.0", "0.1.0"));
        assert!(!super::newer("0.1.0", "0.1.0"));
        assert!(!super::newer("0.0.9", "0.1.0"));
    }
}
